  // Test 126: E1 - anomaly detection (scenario 1)
  (function() {
    try {
      var data = [];
          for (var i = 0; i < 30; i++) {
            var base = 100;
            var noise = (Math.random() - 0.5) * 10;
            data.push({
              timestamp: new Date(Date.now() - (30-i)*600000).toISOString(),
              restarts: i < 25 ? 0 : 1,
              memory: base + noise + (i >= 25 ? 5 : 0),
              responseTime: 200 + noise
            });
          }
          var result = TrendIntelligence.analyzeTrends(data);
          assert.ok(Array.isArray(result.anomalies));
          result.anomalies.forEach(function(a) {
            assert.ok(typeof a.metric === "string");
            assert.ok(typeof a.value === "number");
            assert.ok(typeof a.deviation === "number");
          });
      passed++;
    } catch (e) {
      failed++;
      errors.push("E1 - anomaly detection (scenario 1): " + e.message);
    }
  })();

