  // Test 196: H1 - max 10 recommendations (scenario 1)
  (function() {
    try {
      var incidentSummary = {
            incidentCount: 100,
            incidentsByType: {
              "t1": 10, "t2": 10, "t3": 10, "t4": 10, "t5": 10,
              "t6": 10, "t7": 10, "t8": 10, "t9": 10, "t10": 10, "t11": 10, "t12": 10
            },
            incidentsBySeverity: {critical: 20, warning: 30, info: 50},
            topIncidents: [], meanTimeBetweenIncidents: 0, trend: "increasing"
          };
          var trendSummary = { restartTrend: "increasing", memoryTrend: "increasing", responseTimeTrend: "increasing", predictions: {nextRestartExpected: "soon", memoryWillExceedThreshold: true, recommendedActions: []}, anomalies: [{metric:"memory",value:999,deviation:5}] };
          var result = RecommendationEngine.generateRecommendations(incidentSummary, trendSummary);
          assert.ok(result.recommendations.length <= 10, "Expected <= 10 but got " + result.recommendations.length);
      passed++;
    } catch (e) {
      failed++;
      errors.push("H1 - max 10 recommendations (scenario 1): " + e.message);
    }
  })();

